        "contextWrong": "芬威克在余0旁写下「没有剩余」。「0不是没有信息，它说明正好走完。」",
        "context": "当余数为0时，说明数量正好包含若干个完整周期，没有额外步数。位置通常落在周期的最后一个对应点或回到起点的同类位置。",
