    "lessonSummary": "今天把余数放进周期里：余数表示剩下多少，也能表示循环落点；余0说明完整周期，实际题要先确认循环从哪里开始。",
    "nextLessonPreview": "下一课进入分数乘法。芬威克会把「一个量的几分之几」写成更清楚的乘法。"
