          "leadIn": "芬威克把整张纸称作1，再把半张涂色区域称作新的对象。",
          "text": "求1/2的1/4，第一步要确认什么？",
          "options": [
            "整体是谁",
            "哪个数字更大",
            "粉笔颜色"
          ],
          "answer": 0
