        "contextRight": "他把2/5写在6/15旁边。「同一个结果，路更短。」",
        "contextWrong": "芬威克把可约的3重新圈住。「乘之前能约分，就别把数字养大。」",
        "context": "分数乘法中，任何一个分子的因数都可以和任何一个分母的相同因数约掉。先约分可以减少计算量。",
