    "lessonSummary": "今天进入分数乘法：先确定整体，分子乘分子、分母乘分母，能约分先约分，最后用图形和估算检查大小。",
    "nextLessonPreview": "下一课会处理分数除法。芬威克会把除以一个分数，翻译成乘它的倒数。"
