        "contextWrong": "芬威克把单位箭头画出来。「先看从大单位到小单位，还是从小单位到大单位。」",
        "context": "单位不同的数量不能直接相加或比较。先把它们换成同一种单位，再进行计算。",
        "blackboard": {
          "type": "steps",
          "label": "统一单位",
          "lines": [
            "1米=100厘米",
            "0.75米=0.75×100厘米",
            "=75厘米"
          ],
          "note": "计算前先统一单位。"
        }
