    "lessonSummary": "今天把小数、分数、百分数混合处理：先统一写法，百分号先翻译，计算前估算范围，最后检查答案类型和单位。",
    "nextLessonPreview": "下一课会进入比。两个量之间的顺序会变得非常重要。"
