        "contextRight": "芬威克点了点40。「折扣后低于原价，方向对。」",
        "contextWrong": "他把八折放在100%左边。「折扣题答案应小于原价。」",
        "context": "比例与百分比混合题完成后，要检查结果方向、单位和问题类型是否匹配。",
