    "lessonSummary": "今天学习等腰三角形：两条相等的边叫腰，底角相等；角度题用底角相等和内角和180°共同求解并检查。",
    "nextLessonPreview": "下一课会整理四边形分类。四条边和四个角会给图形不同的名字。"
