        "contextRight": "他把缺失的第3行补上。「顺序让漏洞露出来。」",
        "contextWrong": "芬威克指向行号。「跳着写，自己也难检查。」",
        "context": "列表法要按规律尝试，并用条件筛选不符合的情况。",
