    "lessonSummary": "今天用数轴、等值表示、运算顺序和错题复盘整理了一年级的数与运算。复盘不是背答案，而是把答案放回规则里检查。",
    "nextLessonPreview": "下一课会把这种复盘方法放到比例和代数里：先看两个量怎样对应，再判断式子有没有保持同一个关系。"
