    "lessonSummary": "今天复盘了比例和代数：比例要守住对象顺序，正反比例要先找不变量，字母要说明身份，方程要保持等式平衡。",
    "nextLessonPreview": "下一课会转到几何与数据。图形题先把已知条件画清楚，数据题先问自己要比较什么。"
