        "contextWrong": "他把外沿和内部区域分开标出来。「周长沿边走，面积铺里面。」他说，「别让单位替你暴露错误。」",
        "context": "周长描述边界的总长度，面积描述平面区域的大小，体积描述空间占据的大小。计算后要检查单位是否对应。",
