    "opening": "「一年级结课测验与讲评。」他说，「今天不是看谁先冲到答案。先判断题目属于哪一类，再决定用哪一种工具。」他把粉笔递到黑板前，又收回来，「最后一课，过程要能让别人沿着走一遍。」",
